"""Build a portable, script-free website and a real static testnet explorer."""
import argparse,datetime,hashlib,html,json,shutil
from decimal import Decimal
from pathlib import Path
P=argparse.ArgumentParser();P.add_argument('--snapshot',type=Path,required=True);P.add_argument('--output',type=Path,required=True);a=P.parse_args()
ROOT=Path(__file__).resolve().parents[1];OUT=a.output.resolve();OUT.mkdir(parents=True,exist_ok=True)
S=json.loads(a.snapshot.read_text(encoding='utf-8'));BLOCKS=S['blocks'];BY_HEIGHT={b['height']:b for b in BLOCKS}
TX={t['txid']:(b,t) for b in BLOCKS for t in b['tx']};ADDR={}
for b,t in TX.values():
    for output in t['vout']:
        address=output['scriptPubKey'].get('address')
        if address:ADDR.setdefault(address,[]).append((b,t,output))
E=lambda x:html.escape(str(x),quote=True)
def utc(t):return datetime.datetime.fromtimestamp(t,datetime.timezone.utc).strftime('%d %b %Y, %H:%M:%S UTC')
def amount(v):return f'{Decimal(str(v)):,.8f}'
CAPTURE=datetime.datetime.fromisoformat(S['captured_at']).strftime('%d %b %Y, %H:%M:%S UTC')
ORIGIN='https://obsoletecoin.pages.dev'
GITHUB='https://github.com/jcib/obsoletecoin'
for folder in ('assets','downloads','explorer/blocks','explorer/transactions','explorer/addresses'):(OUT/folder).mkdir(parents=True,exist_ok=True)
for f in (ROOT/'website/assets').iterdir():shutil.copyfile(f,OUT/'assets'/f.name)
DOWNLOADS=[('windows-wsl.zip',ROOT.parent/'ObsoleteCoin-Windows-WSL.zip'),('linux-x64.tar.gz',ROOT/'.local/artifact/obsoletecoin-linux-experimental.tar.gz')]
CHECKSUMS={}
for name,path in DOWNLOADS:
    data=path.read_bytes();CHECKSUMS[name]=hashlib.sha256(data).hexdigest();(OUT/'downloads'/name).write_bytes(data)
(OUT/'downloads/SHA256SUMS.txt').write_text(''.join(f'{v}  {k}\n' for k,v in CHECKSUMS.items()),encoding='utf-8')
(OUT/'explorer/snapshot.json').write_text(json.dumps(S,indent=2),encoding='utf-8')

def write_page(path,title,content,active='home'):
    depth=len(Path(path).parts)-1;r='../'*depth
    nav=[('home','index.html','Home'),('downloads','downloads.html','Downloads'),('explorer','explorer/index.html','Block explorer'),('coin','coin.html','The coin'),('mining','mining.html','How to mine'),('faq','faq.html','Questions & answers')]
    links=''.join(f'<a href="{r}{url}"'+(' class="current" aria-current="page"' if key==active else '')+f'>{label}</a>' for key,url,label in nav)
    doc=f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{E(title)} | Obsolete Coin</title><meta name="description" content="Old things last a lifetime. Obsolete Coin: a deliberately slow, CPU-mined experimental cryptocurrency. Testnet downloads and a real HTML blockchain archive.">
<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><meta name="theme-color" content="#080d37">
<meta property="og:title" content="Obsolete Coin - Old things last a lifetime."><meta property="og:description" content="A little corner of the old internet. CPU mining, slow blocks, and a testnet you can explore."><meta property="og:url" content="{ORIGIN}/{E(path)}">
<link rel="icon" href="{r}assets/floppy.svg" type="image/svg+xml"><link rel="stylesheet" href="{r}assets/style.css"></head>
<body><a class="skip" href="#content">Skip to content</a><div class="site"><div class="topline"><span>THE OBSOLETE COIN HOMEPAGE</span><span>HANDCRAFTED HTML &middot; SMALL BY DESIGN</span></div>
<div class="frame"><div class="titlebar"><a href="{r}index.html">&#9632; Obsolete Coin &mdash; {E(title)}</a><span class="chrome" aria-hidden="true">_ &#9633; &times;</span></div>
<div class="notice">EXPERIMENTAL TESTNET v0.2 &nbsp; &bull; &nbsp; Test coins have no monetary value. <a href="{r}faq.html#mainnet">Mainnet is not live.</a></div>
<div class="layout"><aside class="sidebar"><div class="section-label">YOU ARE HERE</div><nav class="nav" aria-label="Main navigation">{links}<a href="{GITHUB}">GitHub &#8599;</a></nav>
<div class="sidebar-box"><strong>Still here.<br>Still obsolete.</strong><p>A small corner of the internet for a very slow coin.</p><p class="tiny dim">No rush. Bring your CPU.</p></div>
<div class="sidebar-box"><div class="tiny">BLOCKS IN THIS ARCHIVE</div><div class="counter">{len(BLOCKS):06d}</div><div class="tiny dim">Real blocks. Static snapshot.</div></div>
<div class="sidebar-box"><span class="badge yellow">HTML INSIDE</span><span class="badge pink">CPU POWERED</span><span class="badge">TESTNET ONLY</span><p class="tiny dim">Best viewed with a little patience.</p></div></aside>
<main class="content" id="content">{content.replace('@ROOT@',r)}</main></div>
<footer class="footer"><div class="footer-links"><a href="{r}index.html">Home</a><a href="{r}downloads.html">Downloads</a><a href="{r}explorer/index.html">Explorer</a><a href="{r}roadmap.html">Road to mainnet</a><a href="{GITHUB}">Source on GitHub</a></div>
<p class="slogan-small">Old things last a lifetime.</p><div class="footer-badges"><span class="badge">NO JAVASCRIPT</span><span class="badge pink">KEEP A BACKUP</span><span class="badge yellow">BUILT TO LINGER</span></div>
<div class="tiny">Obsolete Coin &middot; Experimental software &middot; Page archive: {E(CAPTURE)}<br>Right click. View source. Make yourself at home.</div></footer></div></div></body></html>"""
    (OUT/path).write_text(doc,encoding='utf-8')

def download_cards():
    return """<div class="download-grid"><article class="download"><h3><img src="@ROOT@assets/floppy.svg" alt="">Windows + WSL</h3><p>The testnet wallet, local node and CPU miner. Requires Debian in WSL.</p><a class="button" href="@ROOT@downloads/windows-wsl.zip" download>DOWNLOAD .ZIP &darr;</a><div class="minor">v0.2 &middot; x86-64 &middot; <a href="@ROOT@mining.html#windows">Setup instructions</a></div></article>
<article class="download"><h3><img src="@ROOT@assets/floppy.svg" alt="">Linux</h3><p>The testnet node, command-line tools and retro desktop wallet.</p><a class="button" href="@ROOT@downloads/linux-x64.tar.gz" download>DOWNLOAD .TAR.GZ &darr;</a><div class="minor">v0.2 &middot; x86-64 &middot; <a href="@ROOT@mining.html#linux">Setup instructions</a></div></article></div>"""

latest=''.join(f'<li><a href="explorer/blocks/{b["height"]}.html">Block #{b["height"]}</a><span>{len(b["tx"])} tx</span></li>' for b in reversed(BLOCKS[-5:]))
home=f"""<section class="hero"><div class="hero-line"><img class="floppy" src="assets/floppy.svg" alt="A pixel-art floppy disk"><h1>OBSOLETE<br>COIN</h1></div><p class="slogan">Old things last a lifetime.</p><p class="intro">A deliberately slow coin. A thoroughly old-fashioned home.</p><p class="micro">CPU MINED &nbsp; / &nbsp; SLOW BY DESIGN &nbsp; / &nbsp; NO PREMINE</p><span class="stamp">STILL WORKS.</span></section>
<h2 class="section-head">Take a copy home <small>[ TESTNET DOWNLOADS ]</small></h2>{download_cards()}
<div class="under-construction"><strong>Native Windows wallet: under construction.</strong> No WSL-free .exe yet. It is a requirement before mainnet. <a href="roadmap.html">See what is next &raquo;</a></div>
<div class="stats"><div><strong>1 BILLION</strong><span>MAXIMUM OBS</span></div><div><strong>15 MIN</strong><span>TARGET BLOCK TIME</span></div><div><strong>YOUR CPU</strong><span>RANDOMX MINING</span></div></div>
<div class="home-columns"><section class="small-window"><div class="window-title">&#9632; THE NOTICE BOARD</div><div class="window-body"><p class="news-date">EXPERIMENTAL RELEASE / v0.2</p><p><strong>The testnet is running.</strong> Mine test coins, try the wallet, and help find the rough edges.</p><p>Early blocks can arrive quickly. The 15-minute interval is a target, not a stopwatch.</p><a href="coin.html">Read the coin's small print &raquo;</a></div></section>
<section class="small-window"><div class="window-title">&#9632; THE BLOCK CABINET</div><div class="window-body"><ul class="block-mini">{latest}</ul><p class="tiny dim" style="">Captured {E(CAPTURE)}. This is an archive, not a live feed.</p><a href="explorer/index.html">Open the block explorer &raquo;</a></div></section></div>
<div class="separator" aria-hidden="true">* * * * *</div><div class="paper"><p><strong>Welcome to the slower side of the internet.</strong> Obsolete Coin is an experimental memecoin with its own blockchain, CPU mining and a soft spot for things that refuse to become fashionable.</p><p>There is no promise of profit here. Just open source code, a test network, and a wallet that looks comfortable on an old desk. <a href="{GITHUB}">Pull up the source on GitHub &raquo;</a> <span class="tiny">Repository access is currently private.</span></p></div>"""
write_page('index.html','Home',home)

checks=''.join(f'<p><strong>{E(k)}</strong><br><code class="hash">{v}</code></p>' for k,v in CHECKSUMS.items())
write_page('downloads.html','Downloads',f"""<h1 class="page-title">The download shelf</h1><p class="lede">Take the whole package. Keep a spare copy.</p>{download_cards()}<div class="under-construction">These are experimental testnet packages. Mainnet wallets and a native Windows installer are not available.</div><h2 class="section-head">What is on the disk?</h2><div class="paper"><ul><li>A full testnet node and a local wallet with send, receive, encryption and backup.</li><li>A single-threaded RandomX reference miner. Mining uses the computer running the node.</li><li>Windows launchers in the WSL ZIP. These use Debian inside WSL; they are not native Windows binaries.</li><li>Build, operation and license documentation.</li></ul><p>The network is currently a private test network. Obtain a peer address from the operator before trying to connect. No public seed network is supplied.</p><p><a href="mining.html">Read the setup guide before opening the package &raquo;</a></p></div><h2 class="section-head">Check your copy</h2><div class="paper"><p>SHA-256 checksums identify these exact files. They are checksums, not signed releases.</p><p><a href="downloads/SHA256SUMS.txt" download>Download SHA256SUMS.txt</a></p>{checks}</div><h2 class="section-head">Other systems</h2><div class="paper"><p><strong>Native Windows:</strong> planned before public launch. <strong>macOS and ARM:</strong> no validated packages in this release.</p><p>Source code: <a href="{GITHUB}">jcib/obsoletecoin</a> (private repository during testing).</p><p class="tiny">Node binaries: source commit 46584f6. Windows launcher fixes: efe2598. Wallet keys, cookies and local balances are not included in any download.</p></div>""",'downloads')

facts=[('Name / working ticker','Obsolete Coin / OBS'),('Mining','RandomX proof of work, CPU'),('Maximum authorized issuance','1,000,000,000 OBS'),('Decimal places','8'),('Target block interval','900 seconds / 15 minutes'),('Difficulty adjustment','ASERT, every block; six-hour half-life'),('Initial block reward','5,000 OBS'),('Halving interval','100,000 blocks, counted from block 1'),('Genesis reward / premine','Zero / none'),('Mining reward maturity','100 blocks'),('End of subsidy','Block 3,900,000; transaction fees thereafter'),('Current network','Experimental testnet v0.2; mainnet disabled')]
write_page('coin.html','The coin',f"""<h1 class="page-title">Old hardware. New blocks.</h1><p class="lede">Simple rules, written down where you can find them.</p><table class="facts"><tbody>{''.join(f'<tr><th scope="row">{E(k)}</th><td>{E(v)}</td></tr>' for k,v in facts)}</tbody></table><h2 class="section-head">Slow is the target</h2><div class="paper"><p>The software does not delay your payment with a timer. Miners produce blocks, and the difficulty adjusts toward an average interval of 15 minutes. Real waits vary. Initial testnet difficulty is deliberately easy.</p><p>More hash power raises difficulty over time; it does not guarantee an exact calendar schedule. The included reference miner uses one CPU thread.</p></div><h2 class="section-head">A finite supply</h2><div class="paper"><p>The integer reward schedule authorizes exactly one billion OBS. A one-off 0.013 OBS rounding remainder is included at the final rewarded block. Unclaimed rewards and lost keys reduce the circulating amount.</p><p>At the target interval, halvings are roughly 2.85 years apart. The inherited timestamp format needs an upgrade before 2106, earlier than the theoretical end of the subsidy schedule.</p></div><h2 class="section-head">Where it comes from</h2><div class="paper"><p>This is a fork of Brisvia and Bitcoin Core, with pinned upstream RandomX. Original licenses are preserved. A Bitcoin-derived codebase does not give a new chain Bitcoin's hash power or security.</p><p><a href="{GITHUB}/blob/main/docs/SPEC.md">Read the full specification on GitHub &raquo;</a></p></div>""",'coin')

write_page('mining.html','How to mine',"""<h1 class="page-title">Bring your CPU.</h1><p class="lede">A small installation guide for a very old-fashioned adventure.</p><div class="snapshot-note"><strong>Testnet only.</strong> Join a participating peer on the private test network. Test balances do not become mainnet coins.</div><div class="paper"><h2 id="windows">Windows + WSL</h2><ol><li>Install Debian in WSL. From an administrator PowerShell:<pre class="code">wsl --install -d Debian</pre>Restart if Windows requests it, then open Debian to finish setup.</li><li>Inside Debian, install the runtime libraries:<pre class="code">sudo apt-get update
sudo apt-get install python3 python3-tk \
  libevent-2.1-7t64 libevent-core-2.1-7t64 \
  libevent-extra-2.1-7t64 libevent-pthreads-2.1-7t64 libsqlite3-0</pre></li><li><a href="downloads/windows-wsl.zip" download>Download the Windows + WSL ZIP</a> and extract it. The prepared launcher uses the operator's home-network peer; use the peer address supplied for your test session.</li><li>Open <code>Start-Mining.cmd</code>. It starts your local node and mines into your local wallet. Keep the window open.</li><li>Open <code>Start-Wallet.cmd</code> to view the wallet. Graphical use requires WSL graphical support. Press Ctrl-C in the mining window to stop.</li></ol><h2 id="linux">Linux x86-64</h2><p>Install the same runtime libraries on Debian 13. Extract the Linux archive, enter the extracted directory and start the node with your peer:</p><pre class="code">python3 tools/node.py --peer YOUR_PEER_IP:19777
# In a second graphical terminal:
python3 tools/wallet.py</pre><p>Choose <strong>Open / Create</strong>, then <strong>Receive</strong>. Choose <strong>Mine / Stop</strong> to start the reference miner.</p><h2>Before you close the window</h2><ul><li>New mining rewards are immature until they satisfy the 100-block maturity rule.</li><li>Your wallet is initially unencrypted. Use <strong>Encrypt</strong>, then make a new private <strong>Backup</strong>. Keep its passphrase safe.</li><li>Keys live on the mining computer. Do not delete its WSL distribution or data directory without a verified wallet backup.</li><li>The current chain is v0.2. Old experimental blocks and balances are incompatible.</li></ul><p><a href="https://github.com/jcib/obsoletecoin/blob/main/docs/WINDOWS.md">Full Windows guide</a> &middot; <a href="https://learn.microsoft.com/windows/wsl/install/">Microsoft's WSL installation guide</a></p></div>""",'mining')

questions=[('mainnet','Is this the real mainnet?','No. This is experimental testnet v0.2. The mainnet is disabled. Test coins have no monetary value and do not automatically carry over to a future mainnet.'),('native','Where is the native Windows wallet?','It is a requirement before mainnet, but it has not been built yet. The available Windows package uses a Linux node and wallet through WSL.'),('speed','Why did my block arrive so quickly?','Initial testnet difficulty is intentionally easy. Fifteen minutes is the target average, not a fixed delay for each transaction or a promise for early test blocks.'),('maturity','I mined coins. Why can I not spend them?','Block rewards must satisfy the 100-block maturity rule. The wallet lists them as immature until they become spendable.'),('security','Do four confirmations make a payment safe?','Not against a miner that dominates a small proof-of-work network. Such a miner can reorganize valid blocks and reverse its own payments. Confirmations are not absolute finality.'),('explorer','Is the explorer live?','No. It is a genuine HTML archive of public blocks and transactions, exported at the time shown on every explorer page. It does not poll a node. New blocks appear only after a new export is published.'),('github','Why does GitHub ask me to sign in?','The source repository is private during testing. You need an account with access. The website does not make the repository public.'),('keys','Can the website recover my wallet?','No. It does not request seed phrases, private keys, wallet files or RPC passwords. Protect your local wallet and keep secure backups.'),('return','Is there a promised return?','No. This is experimental software and a test network, not a promise of income, exchange listing or investment performance.')]
write_page('faq.html','Questions & answers','<h1 class="page-title">The frequently asked bits</h1><p class="lede">A few things worth reading before pressing the big button.</p><div class="paper">'+''.join(f'<details id="{key}"'+(' open' if i==0 else '')+f'><summary>{E(q)}</summary><p>{E(answer)}</p></details>' for i,(key,q,answer) in enumerate(questions))+'</div>','faq')
write_page('roadmap.html','Road to mainnet',"""<h1 class="page-title">Still under construction.</h1><p class="lede">A public launch needs more than a charming homepage.</p><div class="paper"><ul class="status-list"><li><b>AVAILABLE</b> Experimental CPU-mined testnet, local wallet, Linux package and Windows-through-WSL launcher.</li><li><b>REQUIRED</b> A native Windows wallet and signed installer, tested on supported Windows versions.</li><li><b>REQUIRED</b> Independent consensus and security review, adversarial network testing and release-build verification.</li><li><b>REQUIRED</b> A public launch plan, independent miners, peer infrastructure and initial-difficulty calibration.</li><li><b>UNSCHEDULED</b> Mainnet. There is no announced release date and no automatic conversion of test coins.</li></ul><p><a href="https://github.com/jcib/obsoletecoin/blob/main/docs/SECURITY.md">Read the current security and launch notes &raquo;</a></p></div>""",'coin')

NOTICE=f'<div class="snapshot-note"><strong>STATIC TESTNET ARCHIVE</strong><br>Captured {E(CAPTURE)}. Blocks {S["first_height"]}&ndash;{S["height"]}. Newer blocks are not shown until the next export. <a href="@ROOT@explorer/snapshot.json" download>Download public snapshot JSON</a>.</div>'
rows=''.join(f'<tr><td class="table-number"><a href="blocks/{b["height"]}.html">#{b["height"]}</a></td><td class="mono"><a href="blocks/{b["height"]}.html">{b["hash"][:16]}&hellip;</a></td><td class="table-number">{len(b["tx"])}</td><td>{E(utc(b["time"]))}</td></tr>' for b in reversed(BLOCKS))
write_page('explorer/index.html','Block explorer',f'<h1 class="page-title">The block cabinet</h1><p class="lede">Real blocks. Real transactions. Filed away in plain HTML.</p>{NOTICE}<div class="stats"><div><strong>{S["height"]}</strong><span>CAPTURED HEIGHT</span></div><div><strong>{len(TX)}</strong><span>ARCHIVED TRANSACTIONS</span></div><div><strong>{len(ADDR)}</strong><span>OUTPUT ADDRESSES</span></div></div><p><a href="addresses/index.html">Browse address activity &raquo;</a> <span class="tiny dim">Use your browser\'s Find command to locate a block height on this page.</span></p><div class="scroll"><table><thead><tr><th scope="col">Height</th><th scope="col">Block hash</th><th scope="col">Tx</th><th scope="col">Block time</th></tr></thead><tbody>{rows}</tbody></table></div>','explorer')
for b in BLOCKS:
    height=b['height'];prev=f'<a href="{height-1}.html">&laquo; Block {height-1}</a>' if height-1 in BY_HEIGHT else 'Start of archive'
    nxt=f'<a href="{height+1}.html">Block {height+1} &raquo;</a>' if height+1 in BY_HEIGHT else 'End of archive'
    facts=[('Block hash',f'<span class="mono hash">{E(b["hash"])}</span>'),('Block time',E(utc(b['time']))),('Confirmations at capture',str(S['height']-height+1)),('Transactions',str(len(b['tx']))),('Size',f'{b["size"]:,} bytes'),('Weight',f'{b["weight"]:,}'),('Difficulty',E(b['difficulty'])),('Target bits',E(b['bits'])),('Nonce',str(b['nonce'])),('Merkle root',f'<span class="mono hash">{E(b["merkleroot"])}</span>')]
    table=''.join(f'<tr><th scope="row">{key}</th><td>{value}</td></tr>' for key,value in facts)
    txrows=''.join(f'<tr><td><a class="mono hash" href="../transactions/{t["txid"]}.html">{t["txid"]}</a></td><td>{"Block reward" if "coinbase" in t["vin"][0] else "Transfer"}</td><td>{len(t["vout"])}</td></tr>' for t in b['tx'])
    write_page(f'explorer/blocks/{height}.html',f'Block {height}',f'<p class="crumb"><a href="../index.html">Explorer</a> / Block {height}</p><h1 class="page-title">Block #{height}</h1>{NOTICE}<p>{prev} &nbsp; | &nbsp; {nxt}</p><table class="facts"><tbody>{table}</tbody></table><h2 class="section-head">Transactions</h2><table><thead><tr><th>Transaction ID</th><th>Type</th><th>Outputs</th></tr></thead><tbody>{txrows}</tbody></table>','explorer')
for txid,(b,t) in TX.items():
    outs=[]
    for v in t['vout']:
        addr=v['scriptPubKey'].get('address');target=f'<a class="mono hash" href="../addresses/{E(addr)}.html">{E(addr)}</a>' if addr else '<span class="mono">'+E(v['scriptPubKey']['type'])+'</span>'
        outs.append(f'<tr><td>{v["n"]}</td><td>{target}</td><td class="table-number">{amount(v["value"])} OBS</td></tr>')
    inputs=[]
    for vin in t['vin']:
        if 'coinbase' in vin:inputs.append('<li>Coinbase input: block reward, created according to the subsidy rules.</li>')
        else:
            source=vin['txid'];label=f'{source}:{vin["vout"]}'
            inputs.append('<li class="mono hash">'+(f'<a href="{source}.html">{label}</a>' if source in TX else E(label)+' (outside this archive)')+'</li>')
    write_page(f'explorer/transactions/{txid}.html','Transaction',f'<p class="crumb"><a href="../index.html">Explorer</a> / <a href="../blocks/{b["height"]}.html">Block {b["height"]}</a> / Transaction</p><h1 class="page-title">Transaction record</h1>{NOTICE}<div class="paper"><p class="mono hash">{txid}</p><p>Included in <a href="../blocks/{b["height"]}.html">block #{b["height"]}</a>. {S["height"]-b["height"]+1} confirmations at capture.</p><h2>Inputs</h2><ul>{"".join(inputs)}</ul></div><h2 class="section-head">Outputs</h2><div class="scroll"><table><thead><tr><th>Index</th><th>Address / script type</th><th>Amount</th></tr></thead><tbody>{"".join(outs)}</tbody></table></div>','explorer')
address_items=''.join(f'<li><a class="mono hash" href="{E(addr)}.html">{E(addr)}</a> &mdash; {len(outputs)} recorded outputs</li>' for addr,outputs in sorted(ADDR.items()))
write_page('explorer/addresses/index.html','Address index',f'<p class="crumb"><a href="../index.html">Explorer</a> / Addresses</p><h1 class="page-title">The address book</h1>{NOTICE}<div class="paper"><p>Public output addresses found in this archive. These records do not identify people and are not wallet balances.</p><ul class="address-index">{address_items}</ul></div>','explorer')
for addr,records in ADDR.items():
    rows=''.join(f'<tr><td><a href="../blocks/{b["height"]}.html">#{b["height"]}</a></td><td><a class="mono hash" href="../transactions/{t["txid"]}.html">{t["txid"][:20]}&hellip;</a></td><td class="table-number">{amount(v["value"])} OBS</td></tr>' for b,t,v in reversed(records))
    write_page(f'explorer/addresses/{addr}.html','Address activity',f'<p class="crumb"><a href="../index.html">Explorer</a> / <a href="index.html">Addresses</a></p><h1 class="page-title">Address activity</h1>{NOTICE}<div class="paper"><p class="mono hash">{E(addr)}</p><p>{len(records)} outputs recorded in this archive. This is an output history, <strong>not a current spendable balance</strong>.</p></div><h2 class="section-head">Recorded outputs</h2><div class="scroll"><table><thead><tr><th>Block</th><th>Transaction</th><th>Output amount</th></tr></thead><tbody>{rows}</tbody></table></div>','explorer')
write_page('404.html','Wrong turn','<h1 class="page-title">This floppy is empty.</h1><div class="paper"><p>The page you are looking for is not in this archive.</p><p><a href="index.html">Return to the homepage &raquo;</a></p></div>')
(OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n',encoding='utf-8')
print(json.dumps({'html_pages':len(list(OUT.rglob('*.html'))),'blocks':len(BLOCKS),'transactions':len(TX),'addresses':len(ADDR),'captured_at':CAPTURE,'downloads':CHECKSUMS}))
